import { ChatSDKError } from '../error/ChatSDKError';

import { Customer } from './Customer';

export class CustomerInstance {
  private static instance: Customer;

  public static getInstance(): Customer {
    if (!CustomerInstance.instance) {
      CustomerInstance.instance = new Customer();
    }

    return CustomerInstance.instance;
  }

  public static setInstance(customer: Customer): void {
    if (!(customer instanceof Customer)) {
      throw new ChatSDKError(
        'CustomerInstance.setInstance expects a Customer instance',
      );
    }

    CustomerInstance.instance = customer;
  }
}
