import { AuthorizeCustomerData } from '@brandembassy/ts-types-chat/dist/awsEvents/AuthorizeCustomer';
import { AwsInputEventType } from '@brandembassy/ts-types-chat/dist/awsEvents/AwsEventType';
import { BrowserFingerprint } from '@brandembassy/ts-types-chat/dist/user/BrowserFingerprint';
import { VisitorId } from '@brandembassy/ts-types-platform/dist/visitor/VisitorId';

import { CHAT_SDK_VERSION } from '../env/version';
import { ThirdPartyCredentials } from '../securedSession/ThirdPartyCredentials';
import { EventPayloadData } from '../sockets/EventPayload';
import { createVisitorPayload } from '../visitor/createVisitorPayload';

export function createAuthorizationPayloadData(
  credentials: ThirdPartyCredentials | null,
  visitorId: VisitorId,
  browserFingerprint?: BrowserFingerprint,
): EventPayloadData<AuthorizeCustomerData> {
  return {
    eventType: AwsInputEventType.AUTHORIZE_CUSTOMER,
    data: {
      authorization: getAuthorization(credentials),
      browserFingerprint,
      disableChannelInfo: true,
      sdkVersion: CHAT_SDK_VERSION,
      sdkPlatform: 'web',
    },
    ...createVisitorPayload(visitorId),
  };
}

function getAuthorization(
  credentials: ThirdPartyCredentials | null,
): AuthorizeCustomerData['authorization'] {
  if (credentials === null) {
    return { authorizationCode: null };
  }

  if (credentials.grantType === 'implicit') {
    return { accessToken: credentials.accessToken };
  }

  return {
    authorizationCode: credentials.authorizationCode,
    // Conditional: forwarded verbatim to digital-oauth, which rejects a blank code_verifier.
    ...(credentials.codeVerifier && {
      codeVerifier: credentials.codeVerifier,
    }),
  };
}
