import { ChatSDKError } from './ChatSDKError';

/**
 * Extracts the server-provided error code from a ChatSDKError produced by
 * buildResponseError(), where the parsed response body is stored under
 * data.errorResponseData. Centralized so every "is<X>Error" detector reads
 * the same path — this shape is a property of ChatSDKError itself, not of
 * authorization specifically, so it lives alongside the class rather than
 * with the (currently authorization-only) detectors that use it.
 */
export function getChatSDKErrorCode(error: unknown): string | undefined {
  if (!(error instanceof ChatSDKError)) {
    return undefined;
  }

  const data = error.data as
    | { errorResponseData?: { errorCode?: string } }
    | undefined;

  return data?.errorResponseData?.errorCode;
}
