import {
  HeartBeatState,
  setupSocketConnection,
  WebSocketClient as PushUpdateWSClient,
  WebSocketClientEvent as PushUpdatesWebSocketClientEvent,
} from '@brandembassy/push-updates-sdk';
import { BrandId } from '@brandembassy/ts-types-platform/dist/brand/BrandId';
import { ChannelId } from '@brandembassy/ts-types-platform/dist/channel/ChannelId';
import { CustomerIdentityIdOnExternalPlatform } from '@brandembassy/ts-types-platform/dist/endUser/EndUserIdentityId';
import { VisitorId } from '@brandembassy/ts-types-platform/dist/visitor/VisitorId';

import { CaptchaRequiredError } from '../error/CaptchaRequiredError';
import { ChatSDKError } from '../error/ChatSDKError';
import { IpAddressBlockedError } from '../error/IpAddressBlockedError';
import { ChatCustomEvent } from '../event/ChatEvent';
import { isSecureSessions } from '../securedSession/getSecuredSessionType';
import { SDKVariableStorage } from '../variables/VariableStorage';

import { WebSocketClientError } from './WebSocketClientError';
import { WebSocketConnectionError } from './WebSocketConnectionError';
import { IWsEventTarget, WsEventTarget } from './WsEventTarget';

export interface SocketQueryParameters {
  [key: string]: string | number | undefined;
  brandId: BrandId;
  channelId: ChannelId;
  consumerId: CustomerIdentityIdOnExternalPlatform;
  token?: string;
  visitorId: VisitorId;
}

const MAX_SOCKET_RECONNECT_RETRIES = 20;

interface ErrorEventLike {
  error?: unknown;
  message: string;
}

interface CloseEventLike {
  reason: string;
}

/**
 * The socket events below are matched structurally rather than with
 * `instanceof ErrorEvent` / `instanceof CloseEvent`. The underlying
 * ReconnectingWebSocket inside push-updates-sdk currently constructs the DOM
 * globals, but it is free to ship its own `ErrorEvent`/`CloseEvent` classes
 * instead (other copies of that library do exactly that) — and a cross-class
 * `instanceof` would then fail silently, downgrading every specific branch in
 * `_errorHandler` to generic `Unknown error` noise with nothing to catch it.
 * A native `ErrorEvent` always carries a string `message` and never a
 * `reason`; a native `CloseEvent` is the mirror image, so both shapes stay
 * unambiguous.
 */
function isErrorEventLike(event: unknown): event is ErrorEventLike {
  return (
    typeof event === 'object' &&
    event !== null &&
    typeof (event as ErrorEventLike).message === 'string'
  );
}

function isCloseEventLike(event: unknown): event is CloseEventLike {
  return (
    typeof event === 'object' &&
    event !== null &&
    typeof (event as CloseEventLike).reason === 'string'
  );
}

/**
 * Websocket client
 */
export class WebSocketClient {
  #connection: PushUpdateWSClient | null = null;
  #eventTarget: IWsEventTarget;
  #alreadyConnected: boolean = false;

  constructor(
    private onError: ((error: Error) => void) | undefined,
    private socketURLGetter: () => Promise<string>,
  ) {
    this.#eventTarget = new WsEventTarget();
  }

  /**
   * Connect websocket
   */
  async connect(): Promise<void> {
    this.#setupConnection();

    this.#connection?.socket?.reconnect();
  }

  /**
   * Disconnect websocket
   */
  disconnect(): void {
    this.#connection?.socket.close();
  }

  /**
   * Reconnect websocket
   */
  reconnect(): void {
    this.#setupConnection();
    this.#connection?.socket.reconnect();
  }

  /**
   * Send data to active connection
   * @param data - data to send
   */
  send(data: unknown): void {
    const stringData = JSON.stringify(data);
    this.#connection?.send(stringData);
  }

  /**
   * Register event handler to websocket event
   * @param eventType - websocket event
   * @param handlerCallback - event handler
   */
  on(
    eventType: PushUpdatesWebSocketClientEvent,
    handlerCallback: (event: ChatCustomEvent) => void,
  ): void {
    this.#eventTarget.addEventListener(eventType, handlerCallback);
  }

  /**
   * Unregister event handler to websocket event
   * @param eventType - websocket event
   * @param handlerCallback - event handler
   */
  off(
    eventType: PushUpdatesWebSocketClientEvent,
    handlerCallback: (event: CustomEvent) => void,
  ): void {
    this.#eventTarget.removeEventListener(eventType, handlerCallback);
  }

  /**
   * Handle error from event listeners with onError callback or throw error
   */
  private _errorHandler(
    event: CustomEvent<CloseEvent | ErrorEvent | Event>,
  ): void {
    const eventError = event.detail;

    if (
      typeof this.onError === 'function' &&
      isErrorEventLike(eventError) &&
      this.#isSocketURLGetterRejection(eventError.error)
    ) {
      // socketURLGetter (ChatSdk's #createSocketUrl) rejected with one of
      // these specific types, and the caller that rejected it already
      // reported this exact error through this same onError callback.
      // Reporting it again as a generic WebSocketClientError would just be
      // duplicate, less-specific noise. Gated on onError being set so the
      // no-onError `throw error` fallback below is never silently skipped.
      return;
    }

    let error: WebSocketClientError | undefined;

    if (isErrorEventLike(eventError)) {
      error = new WebSocketClientError('Connection error', eventError.message);
    }
    if (isCloseEventLike(eventError)) {
      error = new WebSocketClientError('Connection closed', eventError.reason);
      if (this.#connection?.heartBeatState === HeartBeatState.DIED) {
        error = new WebSocketConnectionError(
          'Websocket connection disconnected',
          'HeartBeat died',
        );
      }
    }
    if (typeof error === 'undefined') {
      error = new WebSocketClientError('Unknown error', eventError.type);
    }

    if (typeof this.onError === 'function') {
      this.onError(error);
    } else {
      throw error;
    }
  }

  /**
   * True only when `error` is one of the specific types the caller-supplied
   * socketURLGetter is known to reject with (ChatSdk's #createSocketUrl
   * throws these on a failed authorization grant) — not a generic
   * `instanceof Error` check, so an unrelated library change that starts
   * populating ErrorEvent.error can't silently disable real error reporting
   * above.
   */
  #isSocketURLGetterRejection(error: unknown): boolean {
    return (
      error instanceof ChatSDKError ||
      error instanceof CaptchaRequiredError ||
      error instanceof IpAddressBlockedError
    );
  }

  #setupConnection(): void {
    // if secured session is ON; start the heartbeat right away because there is no authorization response from lambda
    const heartbeatAfterAuthorize = !isSecureSessions();

    const endpoint = SDKVariableStorage.ENDPOINT_GATEWAY ?? '';
    const forceSecureProtocol = endpoint.startsWith('wss');

    this.#connection = setupSocketConnection(this.socketURLGetter, {
      forceSecureProtocol,
      startClosed: true,
      heartbeatAfterAuthorize,
      maxRetries: 0, // Disable reconnection attempts on the initial connection to avoid retrying in case of an authorization error. Configure maxRetries later once the connection is successfully established.
    });

    const errorHandlerBound = this._errorHandler.bind(this);
    this.#connection?.addEventListener(
      PushUpdatesWebSocketClientEvent.CLOSE,
      errorHandlerBound,
    );
    this.#connection?.addEventListener(
      PushUpdatesWebSocketClientEvent.ERROR,
      errorHandlerBound,
    );

    this.#connection?.addEventListener(
      PushUpdatesWebSocketClientEvent.OPEN,
      (event: CustomEvent<Event>) => {
        this.#connection?.socket.setMaxRetires(MAX_SOCKET_RECONNECT_RETRIES);
        this.#alreadyConnected = true;
        this.#socketEventHandler(event);
      },
    );
    this.#connection?.addEventListener(
      PushUpdatesWebSocketClientEvent.CLOSE,
      (event: CustomEvent<CloseEvent>) => {
        const connection = this.#connection;
        if (!this.#alreadyConnected) {
          // if the connection was not establish before close event.
          // It is most probably because of the Authorization failed
          this.#eventTarget.dispatchEvent(
            new CustomEvent(
              PushUpdatesWebSocketClientEvent.AUTHORIZATION_FAILED,
            ),
          );

          return;
        }

        const maxRetries =
          connection?.socket.getMaxRetires() ?? MAX_SOCKET_RECONNECT_RETRIES;

        if (
          connection &&
          connection.socket.retryCount > 0 &&
          connection.socket.retryCount < maxRetries
        ) {
          this.#eventTarget.dispatchEvent(
            new CustomEvent(PushUpdatesWebSocketClientEvent.RECONNECTING),
          );

          return;
        }

        this.#socketEventHandler(event);
      },
    );
    this.#connection?.addEventListener(
      PushUpdatesWebSocketClientEvent.MESSAGE,
      this.#socketEventHandler,
    );
  }

  #socketEventHandler = (
    event: CustomEvent<CloseEvent | ErrorEvent | Event>,
  ): void => {
    this.#eventTarget.dispatchEvent(event);
  };
}
