/** Credentials for the `authorization_code` grant, optionally with a PKCE verifier. */
export interface ThirdPartyAuthorizationCodeCredentials {
  authorizationCode: string;
  codeVerifier?: string;
  grantType: 'authorization_code';
}

/** Credentials for the `implicit` grant: an access token the integrator already holds. */
export interface ThirdPartyImplicitCredentials {
  accessToken: string;
  grantType: 'implicit';
}

/**
 * Credentials an integrator supplies for 3rd-party OAuth, discriminated by grant type. The
 * pairings are not interchangeable — the backend requires an access token for `implicit` and
 * accepts a PKCE `codeVerifier` only with `authorization_code` — so the union keeps an invalid
 * combination unrepresentable.
 */
export type ThirdPartyCredentials =
  | ThirdPartyAuthorizationCodeCredentials
  | ThirdPartyImplicitCredentials;

/**
 * The grant types accepted at runtime. Keyed on the union rather than listed, so a new grant fails
 * to compile here until it is classified.
 */
export const VALID_GRANT_TYPES: Record<
  ThirdPartyCredentials['grantType'],
  true
> = {
  authorization_code: true,
  implicit: true,
};
