export const ERROR_AUTHORIZE_HOSTNAME_NOT_SET = 'Authorize hostname is not set';
export const ERROR_CANNOT_REFRESH_THIRD_PARTY_TOKEN =
  'Cannot refresh ThirdParty token';

export const ERROR_CANNOT_FETCH_TRANSACTION_TOKEN =
  'Failed to fetch transaction token';

export const ERROR_IP_ADDRESS_BLOCKED = 'Your IP address is blocked.';

export const ERROR_CAPTCHA_REQUIRED = 'Captcha verification is required.';

export const getInvalidGrantTypeErrorMessage = (
  grantType: unknown,
  validGrantTypes: Array<string>,
): string =>
  `Invalid grantType ${JSON.stringify(
    grantType,
  )} in third-party credentials. ` +
  `Expected one of: ${validGrantTypes.join(
    ', ',
  )}. Pass an authorization code as a ` +
  `plain string to use the authorization_code grant without naming it.`;

export const getCustomFieldMaxLengthErrorMessage = (
  ident: string,
  maxLength: number,
): string =>
  `Value of custom field "${ident}" exceeds maximum length of ${maxLength} characters`;
