import {
  getPromiseWithResolvers,
  PromiseWithResolvers,
} from './getPromiseWithResolvers';

/**
 * A deferred whose rejection cannot surface as an *unhandled* rejection.
 *
 * The no-op .catch() attached at creation is load-bearing, not cleanup: a
 * rejection that nobody has awaited *yet* would otherwise be reported
 * globally the moment it happens, before a caller gets a chance to await and
 * observe it. Callers that do await still see the rejection through their own
 * derived promise — this only suppresses the ambient warning.
 */
export function createRejectionSafeDeferred(): PromiseWithResolvers<void> {
  const deferred = getPromiseWithResolvers<void>();

  deferred.promise.catch(() => undefined);

  return deferred;
}
