import { ChatSDKError } from '../error/ChatSDKError';
import { getInvalidGrantTypeErrorMessage } from '../error/errorMessages';
import { SDKVariableStorage } from '../variables/VariableStorage';

import {
  ThirdPartyCredentials,
  VALID_GRANT_TYPES,
} from './ThirdPartyCredentials';

function readAccessToken(
  credentials: ThirdPartyCredentials,
): string | undefined {
  return 'accessToken' in credentials ? credentials.accessToken : undefined;
}

function readAuthorizationCode(
  credentials: ThirdPartyCredentials,
): string | undefined {
  return 'authorizationCode' in credentials
    ? credentials.authorizationCode
    : undefined;
}

function readCodeVerifier(
  credentials: ThirdPartyCredentials,
): string | undefined {
  return 'codeVerifier' in credentials ? credentials.codeVerifier : undefined;
}

/**
 * Rejects an object credential whose `grantType` is missing or unsupported. A bare string, `null`
 * and `undefined` are exempt — they carry no discriminant by design.
 *
 * @throws ChatSDKError
 */
export function assertValidThirdPartyCredentials(
  credentials: string | ThirdPartyCredentials | null | undefined,
): void {
  if (
    credentials === null ||
    credentials === undefined ||
    typeof credentials === 'string'
  ) {
    return;
  }

  const validGrantTypes = Object.keys(VALID_GRANT_TYPES);

  if (!validGrantTypes.includes(credentials.grantType)) {
    throw new ChatSDKError(
      getInvalidGrantTypeErrorMessage(credentials.grantType, validGrantTypes),
    );
  }
}

/**
 * Whether the credential the declared grant expects is present and non-blank. Blank counts as
 * absent, so it falls back to `ChatSDKOptions` rather than replacing or erasing it.
 */
function hasThirdPartyCredential(
  credentials: string | ThirdPartyCredentials | null | undefined,
): credentials is string | ThirdPartyCredentials {
  if (credentials === null || credentials === undefined) {
    return false;
  }

  if (typeof credentials === 'string') {
    return credentials !== '';
  }

  return credentials.grantType === 'implicit'
    ? Boolean(readAccessToken(credentials))
    : Boolean(readAuthorizationCode(credentials));
}

/**
 * Widens the shorthand string form to the full credentials object, and carries a PKCE
 * `codeVerifier` from `ChatSDKOptions` onto an authorization code that omits one. An explicitly
 * supplied verifier wins; a blank one counts as absent.
 */
export function normalizeThirdPartyCredentials(
  credentials: string | ThirdPartyCredentials,
): ThirdPartyCredentials {
  const supplied: ThirdPartyCredentials =
    typeof credentials === 'string'
      ? { authorizationCode: credentials, grantType: 'authorization_code' }
      : credentials;

  if (supplied.grantType === 'implicit') {
    return {
      accessToken: readAccessToken(supplied) ?? '',
      grantType: 'implicit',
    };
  }

  return {
    authorizationCode: readAuthorizationCode(supplied) ?? '',
    codeVerifier:
      readCodeVerifier(supplied) ||
      SDKVariableStorage.CODE_VERIFIER ||
      undefined,
    grantType: 'authorization_code',
  };
}

/**
 * Reads the 3rd-party OAuth credentials held in SDK variable storage. `ChatSDKOptions` exposes
 * `accessToken` and `authorizationCode` independently, so both can be stored; implicit wins.
 */
export function getThirdPartyCredentials(): ThirdPartyCredentials | undefined {
  const { AUTHORIZATION_CODE, CODE_VERIFIER, THIRD_PARTY_ACCESS_TOKEN } =
    SDKVariableStorage;

  if (THIRD_PARTY_ACCESS_TOKEN) {
    return { accessToken: THIRD_PARTY_ACCESS_TOKEN, grantType: 'implicit' };
  }

  if (AUTHORIZATION_CODE) {
    return {
      authorizationCode: AUTHORIZATION_CODE,
      codeVerifier: CODE_VERIFIER || undefined,
      grantType: 'authorization_code',
    };
  }

  return undefined;
}

/**
 * Resolves credentials passed directly to a call, falling back to those supplied through
 * `ChatSDKOptions`.
 *
 * @throws ChatSDKError - if an object credential declares no valid `grantType`
 */
export function resolveThirdPartyCredentials(
  credentials?: string | ThirdPartyCredentials,
): ThirdPartyCredentials | null {
  assertValidThirdPartyCredentials(credentials);

  if (hasThirdPartyCredential(credentials)) {
    return normalizeThirdPartyCredentials(credentials);
  }

  return getThirdPartyCredentials() ?? null;
}

/**
 * Persists credentials for the authorize call. The write is authoritative — the other grant's slots
 * are cleared — because the secured-session path re-reads them from storage. Blank credentials
 * write nothing.
 *
 * @throws ChatSDKError - if an object credential declares no valid `grantType`
 */
export function storeThirdPartyCredentials(
  credentials: string | ThirdPartyCredentials,
): void {
  assertValidThirdPartyCredentials(credentials);

  if (!hasThirdPartyCredential(credentials)) {
    return;
  }

  const normalized = normalizeThirdPartyCredentials(credentials);

  if (normalized.grantType === 'implicit') {
    SDKVariableStorage.THIRD_PARTY_ACCESS_TOKEN = normalized.accessToken;
    delete SDKVariableStorage.AUTHORIZATION_CODE;
    delete SDKVariableStorage.CODE_VERIFIER;

    return;
  }

  delete SDKVariableStorage.THIRD_PARTY_ACCESS_TOKEN;
  SDKVariableStorage.AUTHORIZATION_CODE = normalized.authorizationCode;
  SDKVariableStorage.CODE_VERIFIER = normalized.codeVerifier;
}
